#!/usr/bin/env python3
"""Stable-category verification for A = k C_6 / rad^3.

Right-module convention.  M(i,l) is the uniserial module of length l with
composition factors S_i,...,S_{i+l-1}.  The script:
  * constructs quiver representations of all indecomposable modules;
  * computes Hom spaces by solving the arrow-commutativity equations;
  * quotients by maps factoring through the six indecomposable projectives;
  * verifies the syzygy/suspension orbit generated by S_1;
  * prints the stable Hom and Ext^1 matrices for the four kernel objects.

The computation is characteristic-independent: all matrices have entries 0,1.
"""
from __future__ import annotations

import sympy as sp
from dataclasses import dataclass
from typing import List, Tuple

N = 6
LOEWY = 3

@dataclass
class Module:
    top: int          # 0-based vertex
    length: int
    name: str

    def __post_init__(self) -> None:
        self.top %= N
        self.dims = [0] * N
        for r in range(self.length):
            self.dims[(self.top + r) % N] = 1
        self.arrows = []
        for i in range(N):
            src = self.dims[i]
            tgt = self.dims[(i + 1) % N]
            within_support = src and tgt and ((i - self.top) % N) < self.length - 1
            self.arrows.append(sp.Matrix([[1]]) if within_support else sp.zeros(tgt, src))


def mod(i: int, length: int, name: str | None = None) -> Module:
    return Module(i - 1, length, name or f'M({i},{length})')


def hom_basis(x: Module, y: Module) -> List[List[sp.Matrix]]:
    variables = []
    components = []
    for i in range(N):
        rows, cols = y.dims[i], x.dims[i]
        entries = list(sp.symbols(f'x{i}_0:{rows * cols}')) if rows * cols else []
        variables.extend(entries)
        components.append(sp.Matrix(rows, cols, entries) if entries else sp.zeros(rows, cols))

    equations = []
    for i in range(N):
        equations.extend(list(y.arrows[i] * components[i] - components[(i + 1) % N] * x.arrows[i]))

    if not variables:
        return []
    coefficient, _ = sp.linear_eq_to_matrix(equations, variables)
    basis = []
    for vector in coefficient.nullspace():
        substitution = dict(zip(variables, vector))
        basis.append([matrix.subs(substitution) for matrix in components])
    return basis


def compose(f: List[sp.Matrix], g: List[sp.Matrix]) -> List[sp.Matrix]:
    """Composition g o f."""
    return [g[i] * f[i] for i in range(N)]


def flatten(f: List[sp.Matrix]) -> sp.Matrix:
    return sp.Matrix([entry for component in f for entry in list(component)])


def stable_hom_data(x: Module, y: Module) -> Tuple[int, int, int]:
    hom = hom_basis(x, y)
    ambient_rows = sum(x.dims[i] * y.dims[i] for i in range(N))
    H = sp.Matrix.hstack(*[flatten(f) for f in hom]) if hom else sp.zeros(ambient_rows, 0)

    through_projectives = []
    for i in range(1, N + 1):
        p = mod(i, LOEWY, f'P{i}')
        for f in hom_basis(x, p):
            for g in hom_basis(p, y):
                through_projectives.append(flatten(compose(f, g)))
    F = sp.Matrix.hstack(*through_projectives) if through_projectives else sp.zeros(ambient_rows, 0)
    ordinary = H.rank()
    factor = F.rank()
    stable = ordinary - factor
    return stable, ordinary, factor


def omega(x: Module) -> Module:
    if x.length >= LOEWY:
        raise ValueError('Omega is only used for nonprojective indecomposables.')
    return mod((x.top + x.length) % N + 1, LOEWY - x.length,
               f'Omega({x.name})')


def suspension(x: Module) -> Module:
    candidates = [mod(i, l) for i in range(1, N + 1) for l in (1, 2)]
    matches = [y for y in candidates if (omega(y).top, omega(y).length) == (x.top, x.length)]
    if len(matches) != 1:
        raise AssertionError((x, matches))
    return matches[0]


def main() -> None:
    orbit = [mod(1, 1, 'S1')]
    for _ in range(3):
        y = suspension(orbit[-1])
        names = {(4,1):'S4', (5,2):'M(5,2)', (2,2):'M(2,2)'}
        y.name = names.get((y.top+1,y.length), y.name)
        orbit.append(y)

    print('Suspension orbit in D_sg(A)=stable mod-A:')
    for r, x in enumerate(orbit):
        print(f'  X_{r}=S1[{r}] = {x.name}, top={x.top+1}, length={x.length}')
    x4 = suspension(orbit[-1])
    print(f'  X_4 = {x4.name}, top={x4.top+1}, length={x4.length} = X_0')
    assert (x4.top, x4.length) == (orbit[0].top, orbit[0].length)

    print('\nEntries are stable/ordinary/factor-through-projective dimensions.')
    print('Stable Hom^0 matrix:')
    header = '        ' + ' '.join(f'{x.name:>10}' for x in orbit)
    print(header)
    stable_matrix = []
    for x in orbit:
        row = [stable_hom_data(x, y) for y in orbit]
        stable_matrix.append([v[0] for v in row])
        print(f'{x.name:>8} ' + ' '.join(f'{str(v):>10}' for v in row))

    expected = sp.eye(4)
    actual = sp.Matrix(stable_matrix)
    if actual != expected:
        raise AssertionError(f'Unexpected stable Hom matrix: {actual}')

    print('\nExt^1 matrix = stable Hom(X,Y[1]):')
    ext_matrix = []
    for x in orbit:
        row = [stable_hom_data(x, suspension(y))[0] for y in orbit]
        ext_matrix.append(row)
        print(f'{x.name:>8} ' + ' '.join(f'{v:>10}' for v in row))

    print('\nClosed formula checked for shifts -8 <= q <= 8:')
    for r, x in enumerate(orbit):
        for s, y in enumerate(orbit):
            for q in range(-8, 9):
                z = y
                for _ in range(q % 4):
                    z = suspension(z)
                got = stable_hom_data(x, z)[0]
                expected_dim = int((s + q - r) % 4 == 0)
                if got != expected_dim:
                    raise AssertionError((r, s, q, got, expected_dim))
    print('  dim_k Hom(X_r, X_s[q]) = 1 iff s+q-r = 0 mod 4, and 0 otherwise.')
    print('\nAll checks passed.  The full subcategory add{X_0,X_1,X_2,X_3} is')
    print('closed under suspension and every degree-zero morphism is a direct sum of')
    print('scalars and zero maps; hence it is a 4-periodic semisimple triangulated category.')


if __name__ == '__main__':
    main()
